const __quietstartKits = {
"rewardInstall": (// Business policy only. Every target, catalogue and new-app ticket is issued
// and revalidated by the host; this module cannot read a screen or execute input.
function createRewardInstallKit(options = {}) {
  const copy = value => JSON.parse(JSON.stringify(value));
  const clean = value => String(value ?? '').replace(/[\s\u200b\ufeff]/g, '');
  const token = value => typeof value === 'string' && value.length > 0 && value.length <= 240;
  function initial(now, binding = {}) {
    const config = { ...options, ...(binding.stage || {}) };
    config.taskActionText = binding.stage?.taskActionText ?? binding.stage?.actionText ?? config.taskActionText ?? config.actionText;
    config.taskOpenText = binding.stage?.taskOpenText ?? binding.stage?.openText ?? config.taskOpenText ?? config.openText;
    config.taskDoneText = binding.stage?.taskDoneText ?? binding.stage?.doneText ?? config.taskDoneText ?? config.doneText;
    const childMode = token(binding.rowRef) && typeof binding.name === 'string' && !!clean(binding.name);
    for (const key of ['dwellMs', 'maxTasks', 'maxRefreshes', 'targetBalance', 'pointsPerTask', 'scrollSpeed']) {
      if (config[key] !== undefined && (!Number.isSafeInteger(config[key]) || config[key] < (key === 'maxRefreshes' ? 0 : 1))) throw Error('invalid-install-config:' + key);
    }
    if (!childMode && !['targetBalance', 'pointsPerTask', 'maxTasks', 'maxRefreshes', 'dwellMs'].every(key => Number.isSafeInteger(config[key]))) throw Error('incomplete-install-config');
    config.dwellMs ??= 5000; config.cleanupInstalled ??= true; config.scrollSpeed ??= 800;
    return { config, childMode, phase: childMode ? (config.cleanupInstalled ? 'catalog-before' : 'row-tap') : 'balance',
      rowRef: binding.rowRef || '', name: clean(binding.name), actionSequence: binding.actionSequence || 0,
      ownerAbility: copy(binding.ownerAbility || options.ownerAbility || {
        moduleName: binding.returnModuleName || options.returnModuleName || '',
        abilityName: binding.returnAbilityName || options.returnAbilityName || '' }),
      stage: copy(binding.stage || null), nextReadAt: now, startedAt: now, lastObservedAt: now, phaseReads: 0,
      chooserEnabled: Array.isArray(binding.chooserTexts) && binding.chooserTexts.length > 0,
      chooserMaxReads: binding.chooserMaxReads || 9, chooserPollMs: binding.chooserPollMs || 250,
      confirmMaxReads: binding.confirmMaxReads || 16, confirmPollMs: binding.confirmPollMs || 500,
      chooserSelections: 0, chooserSeen: false,
      missingFrames: 0, absentFrames: 0, marketSeen: false, marketAction: '', catalogTicket: '', catalogCount: 0,
      newAppTicket: '', rewardConfirmed: false, done: false, paused: false, transportAvailable: true, note: '',
      completedTasks: 0, refreshes: 0, scrolls: 0, topScrolls: 0, balanceReads: 0, balance: -1, objectiveReached: false };
  }
  function valid(s, now) {
    if (!s || !s.config || !Number.isSafeInteger(now) || now < 0 ||
      !['balance', 'find', 'catalog-before', 'row-tap', 'market-wait', 'install-wait', 'market-close',
        'open-row-wait', 'catalog-delta', 'open-installed', 'chooser', 'dwell', 'launch-owner', 'verify-reward', 'cleanup', 'return-top', 'refresh'].includes(s.phase) ||
      ['actionSequence', 'nextReadAt', 'startedAt', 'phaseReads', 'missingFrames', 'absentFrames',
        'completedTasks', 'refreshes', 'scrolls', 'topScrolls', 'balanceReads', 'catalogCount', 'lastObservedAt',
        'chooserMaxReads', 'chooserPollMs', 'chooserSelections', 'confirmMaxReads', 'confirmPollMs'].some(key => !Number.isSafeInteger(s[key]) || s[key] < 0) ||
      typeof s.name !== 'string' || s.name.length > 160 || typeof s.rowRef !== 'string' || s.rowRef.length > 240 ||
      ['done', 'paused', 'rewardConfirmed', 'childMode'].some(key => typeof s[key] !== 'boolean')) throw Error('invalid-install-checkpoint');
  }
  function output(s, outcome = 'waiting', intent, applied) {
    return { status: s.paused ? 'paused' : s.done ? 'complete' : 'running', outcome,
      checkpoint: s, message: s.note, ...(s.transportAvailable === false ? {transportAvailable:false} : {}), ...(intent ? { intent, applied } : {}) };
  }
  function attempt(s, kind, data, effect, delay = 0) {
    return output(s, 'waiting', { kind, ...data, rowRef: s.rowRef, name: s.name, sequence: s.actionSequence }, { effect, delay });
  }
  function tap(s, targetRef, effect, delay = 0) {
    if (!token(targetRef)) return fail(s, s.lastObservedAt, '声明的目标已失效');
    return attempt(s, 'tap', { targetRef }, effect, delay);
  }
  function fail(s, now, note) {
    s.note = note;
    if (s.childMode) s.done = true;
    else { s.phase = 'balance'; s.nextReadAt = now + 5000; s.balanceReads = 0; }
    return output(s, 'failed');
  }
  function pause(s, reason) { s.paused = true; s.note = reason; return output(s, 'waiting'); }
  function finish(s, now, note = '') {
    s.completedTasks++; s.refreshes = 0; s.scrolls = 0; s.topScrolls = 0;
    s.note = note || '安装任务奖励已确认';
    if (s.childMode) s.done = true;
    else if (s.completedTasks >= s.config.maxTasks) { s.done = true; s.note = `已完成 ${s.completedTasks} 个安装任务，达到工具包上限`; }
    else { s.phase = 'balance'; s.nextReadAt = now; s.balanceReads = 0; }
    return output(s, 'task');
  }
  function rows(f) { return Array.isArray(f.rows) ? f.rows : Array.isArray(f.section?.rows) ? f.section.rows : []; }
  function action(value, wanted, config) {
    const word = wanted === 'install' ? config.taskActionText : wanted === 'open' ? config.taskOpenText : config.taskDoneText;
    return value === wanted || !!word && clean(value) === clean(word);
  }
  function row(s, f, wanted) {
    return rows(f).find(item => item && clean(item.name) === s.name &&
      (!item.rowRef || item.rowRef === s.rowRef) && action(item.action, wanted, s.config));
  }
  function marketMatches(s, m) {
    return !!m && (m.matched === true || m.matchesRow === true) &&
      (typeof m.name === 'string' ? clean(m.name) === s.name : m.matchesRow === true);
  }
  function pageReady(f) { return f.ownerValid === true && (f.pageReady === true || f.taskPage === true) && !f.market?.visible && !f.market?.matched; }
  function catalogue(s, value, before) {
    const ref = typeof value === 'string' ? value : value?.catalogTicket || value?.ref;
    if (!token(ref) || value?.available === false) return false;
    if (before) { s.catalogTicket = ref; s.catalogCount = Number.isSafeInteger(value?.count) && value.count >= 0 ? value.count : 1; }
    else { s.newAppTicket = value?.newAppTicket || value?.newAppRef || ''; }
    return true;
  }
  function returnTop(s) {
    if(s.topScrolls<4)return attempt(s,'swipe',{from:[.55,.62],to:[.55,.88],speed:s.config.scrollSpeed},'return-top');
    s.phase='refresh';return output(s);
  }
  function decide(checkpoint, observation) {
    const now = observation?.now; valid(checkpoint, now);
    const s = copy(checkpoint), f = observation.facts || {}, config = s.config;
    if (s.done || s.paused || now < s.nextReadAt) return output(s, s.done ? 'done' : 'waiting');
    s.lastObservedAt = now;
    const m = f.market;
    if (s.phase === 'catalog-before') {
      if (f.catalogTicket && catalogue(s, f.catalogTicket, true)) s.phase = 'row-tap';
      else return attempt(s, 'catalog-before', {}, 'catalog-before');
    }
    if (s.phase === 'row-tap') {
      if (!pageReady(f)) return fail(s, now, '任务入口已变化');
      const item = row(s, f, 'install');
      return tap(s, item?.targetRef || f.rowTargetRef, 'market-start', 350);
    }
    if (s.phase === 'market-wait') {
      s.phaseReads++;
      if (marketMatches(s, m)) {
        s.marketSeen = true; s.marketAction = m.action || '';
        if (action(m.action, 'open', config)) s.phase = 'market-close';
        else if (action(m.action, 'install', config)) return tap(s, m.actionRef, 'install-start', 1000);
      }
      if (s.phase === 'market-wait') {
        s.nextReadAt = now + 350; return output(s);
      }
    }
    if (s.phase === 'install-wait') {
      s.phaseReads++;
      if (f.frameAvailable !== false) {
        if (!marketMatches(s, m)) { if (++s.missingFrames >= 3) return fail(s, now, '安装期间页面已切换'); }
        else { s.missingFrames = 0; if (action(m.action, 'open', config)) s.phase = 'market-close'; }
      }
      if (s.phase === 'install-wait') {
        s.nextReadAt = now + 1000; return output(s);
      }
    }
    if (s.phase === 'market-close') {
      if (!marketMatches(s, m) || m.windowValid === false) return fail(s, now, '无法确认安装页窗口');
      if (!token(m.closeRef)) return fail(s, now, m.closeAmbiguous ? '安装页关闭按钮不唯一' : '安装已完成，未找到安装页关闭按钮');
      return tap(s, m.closeRef, 'market-closed', 350);
    }
    if (s.phase === 'open-row-wait') {
      s.phaseReads++;
      const found = pageReady(f) ? row(s, f, 'open') : undefined;
      const openRef = found?.targetRef || (pageReady(f) ? f.openRowRef : '');
      if (token(openRef)) {
        s.openTargetRef = openRef;
        s.phase = config.cleanupInstalled && s.catalogTicket && s.catalogCount > 0 ? 'catalog-delta' : 'open-installed';
      } else {
        s.nextReadAt = now + 350; return output(s);
      }
    }
    if (s.phase === 'catalog-delta') {
      if (f.newAppTicket !== undefined) { s.newAppTicket = token(f.newAppTicket) ? f.newAppTicket : ''; s.phase = 'open-installed'; }
      else return attempt(s, 'catalog-delta', { catalogTicket: s.catalogTicket }, 'catalog-delta');
    }
    if (s.phase === 'open-installed') {
      if (!pageReady(f)) return fail(s, now, '任务列表已切换，未打开应用');
      const currentRow = row(s, f, 'open');
      const ref = currentRow?.targetRef || f.openRowRef;
      if (!token(ref)) return fail(s, now, '任务打开入口已变化');
      return tap(s, ref, 'opened', config.dwellMs);
    }
    if (s.phase === 'chooser') {
      const chooser = f.chooser || {}; s.phaseReads++;
      if (chooser.visible) s.chooserSeen = true;
      if (!chooser.visible && (s.chooserSelections > 0 || chooser.externalForeground)) {
        s.phase = 'dwell'; s.nextReadAt = now + config.dwellMs; return output(s);
      }
      if (chooser.visible && s.chooserSelections < 2 && token(chooser.optionRef)) return tap(s,chooser.optionRef,'chooser-selected',s.chooserPollMs);
      s.nextReadAt = now + s.chooserPollMs; return output(s);
    }
    // A foreign app or permission/onboarding prompt remains untouched. Dwell
    // starts only from the acknowledged Open action, then recalls the owner.
    if (s.phase === 'dwell') s.phase = 'launch-owner';
    if (s.phase === 'launch-owner') return attempt(s, 'launch-owner', { ownerAbility: s.ownerAbility }, 'owner-launched', 500);
    if (s.phase === 'verify-reward') {
      s.phaseReads++;
      if (pageReady(f)) {
        const reward = f.reward || {};
        const done = reward.done === true || f.rowStatus === 'done' || !!row(s, f, 'done');
        const pending = reward.pending === true || ['open','action'].includes(f.rowStatus) || !!row(s, f, 'install') || !!row(s, f, 'open');
        if (done) s.rewardConfirmed = true;
        else if (pending) s.absentFrames = 0;
        else if (reward.absent === true || f.rowStatus === 'absent') s.absentFrames++;
        if (s.absentFrames >= 2) s.rewardConfirmed = true;
      }
      if (s.rewardConfirmed) s.phase = 'cleanup';
      else {
        s.nextReadAt = now + s.confirmPollMs; return output(s);
      }
    }
    if (s.phase === 'cleanup') {
      if (!s.rewardConfirmed) return fail(s, now, '缺少领奖确认，未清理应用');
      if (config.cleanupInstalled && token(s.newAppTicket)) return attempt(s, 'uninstall-new',
        { newAppTicket: s.newAppTicket, catalogTicket: s.catalogTicket }, 'cleanup');
      return finish(s, now, config.cleanupInstalled ? '任务已完成；未能唯一确认新装应用，跳过卸载' : '');
    }
    if(s.phase==='return-top')return returnTop(s);
    if (!pageReady(f)) return output(s);
    if (s.phase === 'balance') {
      if (Number.isSafeInteger(f.balance) && f.balance >= 0) {
        s.balance = f.balance;
        if (f.balance >= config.targetBalance) { s.objectiveReached = true; s.done = true; s.note = `当前金币 ${f.balance}，已达到 ${config.targetBalance} 的目标`; return output(s, 'done'); }
        if (s.completedTasks >= config.maxTasks) { s.done = true; return output(s, 'done'); }
        s.phase = 'find'; s.nextReadAt = now; s.note = `当前金币 ${f.balance}，按每任务 ${config.pointsPerTask} 计算还需 ${Math.ceil((config.targetBalance-f.balance)/config.pointsPerTask)} 个`;
        return output(s);
      }
      if (s.balanceReads >= 4) { s.note = '等待确认当前金币'; s.nextReadAt = now + 5000; return output(s); }
      return attempt(s, 'swipe', { from:[.5,.34],to:[.5,.86],speed:config.scrollSpeed }, 'balance-scroll', 250);
    }
    if (s.phase === 'find') {
      const item = rows(f).filter(item => item && token(item.rowRef) && clean(item.name) && token(item.targetRef) && action(item.action,'install',config))[0];
      if (item) {
        s.rowRef = item.rowRef; s.name = clean(item.name); s.catalogTicket = ''; s.catalogCount = 0; s.newAppTicket = ''; s.rewardConfirmed = false;
        s.refreshes = 0; s.scrolls = 0; s.phase = config.cleanupInstalled ? 'catalog-before' : 'row-tap';
        return decide(s,{now,facts:f});
      }
      if (s.scrolls < 3) return attempt(s,'swipe',{from:[.55,.88],to:[.55,.62],speed:config.scrollSpeed},'list-scroll');
      if (s.refreshes >= config.maxRefreshes) { s.done = true; s.note = `连续换一换 ${s.refreshes} 次，遍历任务列表仍没有任务`; return output(s,'done'); }
      s.phase = 'return-top'; s.topScrolls = 0;
    }
    if(s.phase==='return-top')return returnTop(s);
    if (s.phase === 'refresh') {
      if (!token(f.refreshTargetRef)) { s.done = true; s.note = '没有可安装任务，换一换入口不可确认'; return output(s,'done'); }
      return tap(s,f.refreshTargetRef,'refreshed',900);
    }
    return output(s);
  }
  function commit(decision, receipt) {
    if (!decision?.intent || !receipt || !Number.isSafeInteger(receipt.at) || receipt.at < 0 ||
      receipt.sequence !== decision.intent.sequence) throw Error('invalid-install-receipt');
    const s = copy(decision.checkpoint), effect = decision.applied?.effect, at = receipt.at;
    if (receipt.transportAvailable === false || receipt.available === false) s.transportAvailable = false;
    if (effect === 'catalog-before' || effect === 'catalog-delta') {
      if (!['observed','applied','already-applied'].includes(receipt.status) || receipt.available === false) return fail(s,at,'无线调试连接已断开');
      if (effect === 'catalog-before') {
        if (!catalogue(s,receipt,true)) return fail(s,at,'已装应用快照票据无效');
        s.phase = 'row-tap';
      } else {
        const next = receipt.newAppTicket || receipt.newAppRef || '';
        if (next && !token(next)) return fail(s,at,'新增应用票据无效');
        s.newAppTicket = next; s.phase = 'open-installed';
      }
      s.nextReadAt = at; return output(s);
    }
    const applied = receipt.status === 'applied' || receipt.status === 'already-applied';
    if(applied||receipt.consumed===true)s.actionSequence=decision.intent.sequence+1;
    if (!applied) {
      if (effect === 'cleanup' && s.rewardConfirmed) { s.newAppTicket = ''; return finish(s,at,'任务已完成；新应用卸载未确认，不重复卸载'); }
      if (effect === 'owner-launched' && receipt.status === 'failed') return fail(s,at,receipt.transportAvailable === false?'无线调试连接已断开':'未能直接唤回任务应用');
      return pause(s,'输入结果未确认：'+receipt.status+'；不自动重复');
    }
    s.nextReadAt = at + (decision.applied.delay || 0);
    switch(effect) {
      case 'market-start': s.phase='market-wait';s.phaseReads=0;s.marketSeen=false;s.marketAction='';break;
      case 'install-start': s.phase='install-wait';s.phaseReads=0;s.missingFrames=0;break;
      case 'market-closed': s.phase='open-row-wait';s.phaseReads=0;break;
      case 'opened':
        s.phase=s.chooserEnabled?'chooser':'dwell';
        if(s.chooserEnabled){s.phaseReads=0;s.chooserSeen=false;s.chooserSelections=0;s.nextReadAt=at+s.chooserPollMs;}break;
      case 'chooser-selected': s.chooserSelections++;break;
      case 'owner-launched': s.phase='verify-reward';s.phaseReads=0;s.absentFrames=0;s.nextReadAt=at+s.confirmPollMs;break;
      case 'cleanup': s.newAppTicket='';return finish(s,at);
      case 'balance-scroll':s.balanceReads++;break;
      case 'list-scroll':s.scrolls++;s.phase='balance';s.balanceReads=0;break;
      case 'return-top':s.topScrolls++;break;
      case 'refreshed':s.refreshes++;s.scrolls=0;s.topScrolls=0;s.phase='balance';s.balanceReads=0;break;
    }
    return output(s,['list-scroll','return-top','balance-scroll'].includes(effect)?'scroll':effect==='refreshed'?'refresh':'waiting');
  }
  function requests(s) { return {phase:s.phase,rowRef:s.rowRef,name:s.name,catalogTicket:s.catalogTicket,
    ownerAbility:s.ownerAbility,taskRegion:s.config.taskRegion,refreshRegion:s.config.refreshRegion,
    marketNameId:s.config.marketNameId,marketActionId:s.config.marketActionId,marketCloseRegion:s.config.marketCloseRegion}; }
  return {initial,decide,commit,requests,successful:s=>s.done&&!s.paused&&(s.childMode?s.rewardConfirmed:s.objectiveReached||s.completedTasks>=s.config.maxTasks),
    cadence:(s,now)=>Math.max(150,Math.min(1000,s.nextReadAt>now?s.nextReadAt-now:150))};
}),
"rewardStages": (// Platform-neutral extraction of RewardStagesWorker. Native facts own every
// row/target/catalog reference; this Kit never reads a tree or sends input.
function createRewardStages(spec, dependencies = {}) {
  const copy = value => JSON.parse(JSON.stringify(value));
  const compact = value => String(value ?? '').replace(/[\s\u200b\ufeff]/g, '');
  const installKit = dependencies.installKit;
  if (!spec || !Array.isArray(spec.stages) || !spec.stages.length) throw Error('invalid-reward-stages');
  spec = { listScrollX: .52, pageScrollX: .015, scrollTop: .34, scrollBottom: .86,
    chooserTexts: ['选择打开方式'], chooserMaxReads: 9, chooserPollMs: 250, ...copy(spec) };
  function initial(now) {
    return { stageIndex: 0, stageCount: 0, refreshes: 0, scrolls: 0, lastListViewport: '',
      unchangedListReads: 0, seeks: 0, stageSeen: false, adPending: false, adStartedAt: 0,
      done: false, note: '', counts: [], nextReadAt: 0, missingPageReads: 0, exited: false,
      commandAvailable: true, phase: 'scan', phaseReads: 0, absent: 0,
      rowRef: '', rowName: '',
      child: null, chooserSelections: 0, chooserSeen: false, startedAt: now, actionSequence: 0 };
  }
  function valid(s, now) {
    if (!s || !Number.isFinite(now) || !Array.isArray(s.counts) || s.counts.length > spec.stages.length ||
      ['stageIndex','stageCount','refreshes','scrolls','unchangedListReads','seeks','adStartedAt',
       'nextReadAt','missingPageReads','phaseReads','absent',
       'startedAt','actionSequence'].some(key => !Number.isSafeInteger(s[key]) || s[key] < 0) ||
      !['scan','chooser','dwell','wake','confirm-visit','child'].includes(s.phase) ||
      s.stageIndex > spec.stages.length || s.rowRef.length > 240 || s.rowName.length > 160) throw Error('invalid-reward-checkpoint');
  }
  function resetList(s) { s.scrolls = 0; s.lastListViewport = ''; s.unchangedListReads = 0; }
  function output(s, outcome = 'waiting', intent, applied) {
    return { status: s.exited ? 'outside' : s.done ? 'complete' : 'running', outcome,
      checkpoint: s, ...(!s.commandAvailable ? { transportAvailable: false } : {}), ...(intent ? { intent, applied } : {}) };
  }
  function advance(s, reason) {
    s.counts.push(s.stageCount); s.note = `第 ${s.stageIndex + 1} 区结束：${reason}`;
    s.stageIndex++; s.stageCount = 0; s.refreshes = 0; resetList(s); s.seeks = 0;
    s.stageSeen = false; s.adPending = false; s.phase = 'scan'; s.phaseReads = 0;
    if (s.stageIndex >= spec.stages.length) { s.done = true; s.note += '；全部区域已完成'; }
    return output(s, 'stage');
  }
  function fail(s, now, note) { s.note = note; s.nextReadAt = now + 5000; s.phase = 'scan'; return output(s, 'failed'); }
  function exit(s) { s.exited = true; s.note = '已返回免费领好礼入口页'; return output(s, 'outside'); }
  function attempt(s, kind, data, applied) {
    return output(s, 'waiting', { kind, ...data, sequence: s.actionSequence }, applied);
  }
  function tap(s, ref, applied) { return attempt(s, 'tap', { targetRef: ref }, applied); }
  function finishTask(s, now, stage) {
    s.stageCount++; s.refreshes = 0; resetList(s); s.phase = 'scan'; s.phaseReads = 0;
    s.note = `第 ${s.stageIndex + 1} 区完成 ${s.stageCount} 次`;
    return s.stageCount >= stage.maxTasks ? advance(s, '达到次数上限') : output(s, 'task');
  }
  function childResult(s, decision, now) {
    s.child.checkpoint = decision.checkpoint;
    if (decision.transportAvailable === false) s.commandAvailable = false;
    const child = decision.checkpoint;
    if (Number.isSafeInteger(child.actionSequence)) s.actionSequence = child.actionSequence;
    if (Number.isSafeInteger(child.nextReadAt)) s.nextReadAt = child.nextReadAt;
    if (decision.message) s.note = decision.message;
    if (decision.status === 'paused') return { ...decision, checkpoint: s };
    if (decision.status === 'outside' || decision.outcome === 'outside') return exit(s);
    if (decision.status === 'complete') {
      s.child = null;
      return installKit.successful(child) ? finishTask(s, now, spec.stages[s.stageIndex]) :
        fail(s, now, decision.message || '返回后未确认安装任务奖励');
    }
    return output(s, decision.outcome || 'waiting', decision.intent,
      decision.intent ? { effect: 'install-child', decision } : undefined);
  }
  function chooser(s, now, facts, stage) {
    const chooser = facts.chooser || {};
    s.phaseReads++;
    if (chooser.visible) s.chooserSeen = true;
    if (!chooser.visible && (s.chooserSelections > 0 || chooser.externalForeground)) {
      s.phase = 'dwell'; s.nextReadAt = now + stage.dwellMs; return output(s);
    }
    if (chooser.visible && s.chooserSelections < 2 && chooser.optionRef) return tap(s, chooser.optionRef,
      { effect: 'chooser-selected', delay: spec.chooserPollMs });
    s.nextReadAt = now + spec.chooserPollMs; return output(s);
  }
  function decide(checkpoint, observation) {
    const now = observation?.now; valid(checkpoint, now); const s = copy(checkpoint), f = { ...(observation.facts || {}) };
    if (f.taskPage === undefined) f.taskPage = f.pageTextMatched;
    if (!f.video && f.adFrames) f.video = f.adFrames;
    if (s.done || s.exited) return output(s, s.exited ? 'outside' : 'done');
